INSERT INTO catalogo.categorias (id,nombre,slug) VALUES (1,'Anillos','anillos'), (2,'Cadenas','cadenas'), (3,'Collares','collares'), (4,'Grillz','grillz');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (1, 4, 'Grillz Custom Silver Star & Heart', 'Diseño de grillz que combina motivos de estrella y corazón en una propuesta de estilo personalizado. Consulta las opciones de ajuste y composición antes de elegir tu pieza; las medidas no están especificadas en este catálogo.', 90990, 'products/product-1.jpg', '["Grillz", "Estrella", "Corazón", "Personalizado"]', 'new', 'Nuevo', true, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (2, 4, 'Grillz Flor y Media Luna Plata', 'Exclusivo Grillz de plata que destaca por sus intrincados detalles de flor y media luna. Diseñado para un ajuste cómodo y seguro, esta pieza única añade un toque atrevido y brillante a tu estilo. Fabricado con materiales de alta calidad para garantizar un acabado pulido y espectacular.', 90990, 'products/product-2.jpg', '["Plata", "Grillz", "Diseño", "Joyería Custom"]', 'popular', '', true, 0, 0, 'DISPONIBLE');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (3, 2, 'Cadena Eslabón Cubano Oro Rosa', 'Una cadena de eslabón cubano clásica con un acabado premium en oro rosa. Su diseño robusto pero elegante la convierte en una pieza versátil, ideal tanto para uso diario como para destacar en ocasiones especiales. Cuenta con broche de seguridad para mayor tranquilidad.', 105990, 'products/product-3.jpg', '["Oro Rosa", "Eslabón Cubano", "Joyería"]', 'new', 'Oferta', true, 4, 5, 'DISPONIBLE');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (4, 2, 'Cadena Corona Real', 'Imponente cadena con dije de Corona Real finamente esculpido. Una pieza de joyería llamativa que destaca por su elegancia y detalles precisos, ideal para quienes buscan resaltar su estilo con autoridad. Fabricada con materiales de primera calidad para asegurar máxima durabilidad y un brillo excepcional constante.', 219990, 'products/product-4.jpg', '["Corona Real", "Cadenas", "Exclusivo", "Joyería"]', 'popular', '', true, 0, 0, 'DISPONIBLE');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (5, 3, 'Collar Flor de Nácar con Detalles Esmeralda', 'Collar de inspiración floral que combina el aspecto nacarado de su motivo central con detalles de color esmeralda. Una opción para acompañar escotes sencillos y dar protagonismo al colgante. Consulta la longitud, el material de la cadena y la composición de los detalles.', 80000, 'products/product-5.jpg', '["Collar", "Flor", "Nácar"]', 'new', '', true, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (6, 1, 'Anillo Halo Zafiro Azul en Plata', 'Anillo de diseño halo con una pieza central azul rodeada por detalles brillantes. El contraste entre el centro y su contorno resalta la silueta del anillo. Consulta la talla y las especificaciones del metal y de la piedra antes de comprar.', 95990, 'products/product-6.jpg', '["Anillo", "Halo", "Azul"]', 'popular', 'Oferta', true, 4, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (7, 1, 'Anillo Solitario Doble Halo Circonias', 'Diseño solitario de doble halo que destaca la pieza central mediante dos contornos decorativos. Su composición aporta presencia y brillo al conjunto. Consulta las tallas disponibles y las medidas de la pieza central para elegir el ajuste adecuado.', 200990, 'products/product-7.jpg', '["Anillo", "Solitario", "Doble halo", "Circonias"]', 'new', '', true, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (8, 1, 'Anillo Compromiso Oro Blanco y Rosa', 'Anillo de compromiso que combina tonos blanco y rosa en una propuesta de contraste delicado. Puede llevarse como pieza protagonista o junto a una alianza de líneas sencillas. Consulta talla, composición y quilataje; estos datos no están definidos en el catálogo.', 189990, 'products/product-8.jpg', '["Anillo", "Compromiso", "Blanco y rosa"]', 'popular', '', true, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (9, 4, 'Grillz Set Completo Chrome Black & Silver (8 Piezas)', 'Conjunto de grillz presentado como set de ocho piezas, con contraste visual negro y plateado. Un diseño pensado para destacar la sonrisa. Consulta la distribución de las piezas, su composición y el procedimiento de ajuste personalizado.', 180990, 'products/product-9.jpg', '["Grillz", "Set", "Negro", "Plateado"]', 'new', '', false, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (10, 4, 'Grillz Duo Colmillos Plateados', 'Dúo de grillz de apariencia plateada con una silueta inspirada en colmillos. Su diseño concentra el protagonismo en dos piezas. Consulta compatibilidad, composición y ajuste; no intentes modificar la forma por tu cuenta.', 90990, 'products/product-10.jpg', '["Grillz", "Dúo", "Colmillos"]', 'new', 'Oferta', false, 4, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (11, 4, 'Grillz Custom Dos Dientes Estilo tribal / Wave', 'Propuesta de grillz para dos dientes con líneas de inspiración tribal y ondulada. El dibujo aporta movimiento a una composición compacta. Consulta las alternativas de personalización y el método de ajuste antes de encargarla.', 60990, 'products/product-11.jpg', '["Grillz", "Tribal", "Wave", "Personalizado"]', 'new', '', false, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (12, 1, 'Anillo Solitario Oro Rosa con Circonia Corte Brillante', 'Anillo solitario en tono oro rosa con circonia de corte brillante como protagonista del diseño. Sus líneas permiten combinarlo con otras piezas discretas. Consulta talla, dimensiones y composición del aro antes de seleccionar tu pieza.', 150990, 'products/product-12.jpg', '["Anillo", "Solitario", "Rosa", "Circonia"]', 'new', 'Oferta', false, 4, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (13, 1, 'Sello San Benito Oro Laminado 18K', 'Anillo tipo sello con motivo de San Benito, presentado en el catálogo como oro laminado de 18K. El frente decorativo le da una identidad marcada. Consulta las tallas, el metal base y las indicaciones específicas para conservar su acabado.', 210990, 'products/product-13.jpg', '["Anillo", "Sello", "San Benito", "Oro laminado"]', 'new', '', false, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.productos (id,categoria_id,nombre,descripcion,precio_clp,imagen_key,etiquetas,grupo,insignia,destacado,valoracion,cantidad_resenas,disponibilidad) VALUES (14, 1, 'Anillo Signet Oro con Piedra Onix Negra y Circones', 'Anillo tipo signet que combina una piedra central negra con detalles de circones y apariencia dorada. El contraste refuerza el carácter del frente del anillo. Consulta talla, composición del metal y dimensiones para completar la elección.', 230990, 'products/product-14.jpg', '["Anillo", "Signet", "Negro", "Circones"]', 'new', '', false, 0, 0, 'CONSULTAR');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (1, 'como-limpiar-y-conservar-tus-joyas', 'Cómo limpiar y conservar el brillo de tus cadenas y anillos en casa', 'Equipo JA Joyerías', '["Tus joyas son una extensión de tu estilo, pero el uso diario, el sudor, los perfumes y cremas pueden ir opacando su brillo natural. No necesitas ser un experto ni tener maquinaria profesional para mantener tus cadenas y anillos relucientes. Con ingredientes simples que tienes en casa, puedes devolverles la vida.", "El primer consejo y el más efectivo es crear una solución suave. Mezcla agua tibia (no hirviendo) con unas gotas de jabón líquido para platos. Sumerge tus joyas de oro o plata por unos 15 a 20 minutos. Esto aflojará la suciedad acumulada en los eslabones de tus cadenas y en las grietas de tus anillos.", "Para la limpieza profunda, utiliza un cepillo de dientes de cerdas suaves. Cepilla con mucho cuidado, asegurándote de no aplicar demasiada fuerza para evitar micro rayaduras, especialmente en metales más maleables como el oro de 18k o la plata pura.", "Finalmente, enjuaga con agua limpia y seca inmediatamente con un paño de microfibra. Nunca uses toallas de papel, ya que sus fibras son abrasivas. Siguiendo esta rutina una vez al mes, tus piezas de JA Joyerías siempre se verán como recién salidas de la vitrina."]', 'blog/blog-1.jpg', 'PUBLICADO', '2025-02-21 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (2, 'oro-10k-14k-18k-cual-elegir', 'Oro 10k, 14k o 18k: Diferencias, resistencia y cuál elegir para tu joya', 'Equipo JA Joyerías', '["Al momento de invertir en una pieza de joyería, uno de los dilemas más comunes es elegir el quilataje adecuado. Entender qué significa \\"k\\" (quilate) es fundamental: el oro puro es de 24k, pero es demasiado blando para la joyería. Por lo tanto, se mezcla con otras aleaciones (como plata, cobre o zinc) para darle resistencia y durabilidad.", "El oro de 10k contiene un 41.7% de oro puro. Es la opción más resistente y económica, ideal para anillos de uso rudo o cadenas gruesas que podrían sufrir impactos. Por otro lado, el oro de 14k (58.3% oro) es el rey de la joyería moderna, ofreciendo el equilibrio perfecto entre un brillo excepcional, buena durabilidad y un precio accesible.", "Si buscas lujo y prestigio, el oro de 18k es la elección suprema. Con un 75% de pureza, posee un color amarillo rico y profundo que no se puede imitar. Sin embargo, requiere un trato más cuidadoso, ya que es más propenso a rayarse en comparación con el 10k o 14k, por lo que solemos recomendarlo para joyas de ocasiones especiales o anillos de compromiso.", "En JA Joyerías trabajamos con todas estas variaciones. Si tu pieza es un Grillz que estarás usando y retirando constantemente de tu boca, solemos recomendar 10k o 14k por la fricción y resistencia estructural que se necesita."]', 'blog/blog-2.jpg', 'PUBLICADO', '2026-01-03 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (3, 'impresion-dental-para-custom-grillz', 'Guía definitiva: Cómo tomar la impresión dental perfecta para tus custom grillz', 'Equipo JA Joyerías', '["El ajuste es una parte esencial de unos grillz personalizados. Antes de tomar una impresión, consulta con un profesional dental para valorar el estado de dientes y encías y determinar si esta pieza es adecuada para ti. Una fotografía puede servir para conversar sobre el diseño, pero no sustituye un registro preciso de la boca.", "Coordina con el taller qué tipo de registro necesita: una impresión realizada por un profesional o un escaneo compatible con su proceso. Confirma qué dientes cubrirá el diseño y comunica la presencia de brackets, coronas u otras restauraciones. Evita utilizar materiales domésticos o improvisar un molde.", "En la prueba de ajuste, la pieza debe poder colocarse y retirarse sin forzar. Si produce presión, dolor o roces, detén el uso y solicita una revisión. No la dobles ni la pegues a los dientes. Conserva las indicaciones de limpieza y almacenamiento entregadas para tu pieza."]', 'blog/blog-3.jpg', 'PUBLICADO', '2026-03-15 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (4, 'elegir-un-anillo-con-caracter', 'Cómo elegir un anillo con textura y carácter que combine con tu estilo', 'Equipo JA Joyerías', '["Un anillo con textura puede convertirse en el punto de atención de un conjunto sencillo. Observa primero su silueta: un sello ancho tiene una presencia distinta a un aro fino o a un solitario elevado. Elige una forma que te guste tanto de frente como de perfil.", "Para combinarlo, busca un elemento compartido con tus otras piezas: el tono del metal, una piedra del mismo color o una línea geométrica. No es necesario que todas las joyas sean iguales. Dejar espacio entre piezas voluminosas ayuda a que cada diseño se aprecie.", "La comodidad importa tanto como la apariencia. Confirma la talla y el ancho del aro, porque dos anillos de la misma talla nominal pueden sentirse distintos. Revisa también que la textura no se enganche en las prendas que usas habitualmente y consulta sus cuidados específicos."]', 'blog/blog-4.jpg', 'PUBLICADO', '2025-12-30 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (5, 'control-de-calidad-de-nuestras-piezas', 'Del soplete a tu dedo: El riguroso proceso de control de calidad en cada una de nuestras piezas', 'Equipo JA Joyerías', '["El control de calidad de una joya debe atender tanto a su aspecto como a su uso. Una revisión visual permite detectar irregularidades del acabado, bordes ásperos o diferencias entre el diseño acordado y la pieza terminada. La luz uniforme ayuda a observar detalles que pueden pasar inadvertidos en una fotografía.", "En cadenas y collares conviene revisar eslabones, uniones y funcionamiento del cierre. En anillos con piedras, la sujeción debe ser evaluada por una persona cualificada. No intentes comprobarla tirando de las piedras o deformando sus soportes.", "Antes de recibir una pieza, pide que se confirmen talla o longitud, materiales declarados y recomendaciones de mantenimiento. Guarda esa información junto al comprobante de compra. Si observas una irregularidad, comunícala al vendedor para que pueda revisar la pieza y explicar las opciones de solución."]', 'blog/blog-5.jpg', 'PUBLICADO', '2026-05-05 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (6, 'invertir-en-una-joya-de-alto-estandar', 'Piezas de vitrina: En qué fijarte antes de invertir en una joya de alto estándar', 'Equipo JA Joyerías', '["El precio y el brillo no bastan para evaluar una joya. Comienza por conocer qué estás comprando: metal base, pureza cuando corresponda, tipo de recubrimiento y naturaleza de las piedras. Oro macizo, baño de oro y oro laminado describen productos diferentes y requieren expectativas de uso distintas.", "Revisa las proporciones, la comodidad y la terminación de zonas menos visibles, como el interior de un aro o la parte trasera de un colgante. Pregunta qué incluye el precio y qué condiciones se aplican a ajustes, reparaciones y cambios. No deduzcas la composición únicamente por el color de una foto.", "Si la compra es importante, solicita documentación de los materiales y, cuando proceda, certificación independiente de las piedras. Una joya puede tener valor personal y artesanal sin garantizar una rentabilidad futura. Elige con información suficiente y dentro del presupuesto que hayas definido."]', 'blog/blog-6.jpg', 'PUBLICADO', '2026-07-30 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (7, 'mantener-el-brillo-de-tu-cadena-de-oro', 'El secreto para mantener el brillo impecable de tu cadena de oro todos los días', 'Equipo JA Joyerías', '["La forma más sencilla de cuidar una cadena es reducir la acumulación de residuos. Aplícate perfume y cremas antes de colocarla, deja que se sequen y retira la pieza para hacer deporte, bañarte o entrar a una piscina. El cuidado concreto depende del metal y de sus posibles recubrimientos.", "Después de usarla, pasa suavemente un paño adecuado para el acabado. No apliques pulidores abrasivos a piezas bañadas o laminadas sin consultar al fabricante. Si tiene piedras, perlas o adhesivos, confirma el método de limpieza antes de sumergirla o utilizar productos químicos.", "Guárdala seca, separada de otras joyas y con el cierre abrochado para reducir enredos. Comprueba periódicamente el cierre y las uniones. Si notas un eslabón abierto o una zona debilitada, deja de usarla y consulta un servicio de reparación."]', 'blog/blog-7.jpg', 'PUBLICADO', '2026-03-15 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (8, 'higiene-y-cuidados-de-grillz', 'Uso responsable de grillz: Claves de higiene dental y cuidados esenciales para tu sonrisa', 'Equipo JA Joyerías', '["Los grillz son accesorios decorativos y no sustituyen tratamientos dentales. Antes de utilizarlos, consulta con un profesional dental, especialmente si tienes caries, molestias, encías inflamadas o restauraciones. Un diseño atractivo también debe permitir una colocación y retirada sin esfuerzo.", "Retíralos para comer y dormir, no los compartas y mantén la higiene habitual de dientes y encías. Limpia la pieza fuera de la boca siguiendo las instrucciones específicas de sus materiales. No uses pegamentos ni productos de limpieza doméstica para sujetarla o desinfectarla.", "Si aparecen dolor, sensibilidad, irritación o cambios en las encías, suspende el uso y solicita una evaluación dental. No ajustes la pieza doblándola por tu cuenta. Guárdala limpia y seca en su estuche, separada de otras joyas."]', 'blog/blog-8.jpg', 'PUBLICADO', '2026-02-15 00:00:00');
INSERT INTO catalogo.publicaciones (id,slug,titulo,autor_visible,parrafos,portada_key,estado,publicado_en) VALUES (9, 'crear-una-joya-personalizada', 'De tu idea a la realidad: El paso a paso para mandar a hacer una joya personalizada', 'Equipo JA Joyerías', '["Un encargo personalizado comienza con una idea clara. Reúne referencias visuales y describe qué elementos te interesan: forma, tonos, símbolos y tamaño aproximado. Explica también cómo piensas usar la pieza y el presupuesto disponible, para que el diseño pueda adaptarse a esas condiciones.", "Antes de aprobar el trabajo, solicita una propuesta que detalle materiales, medidas, precio, plazos estimados y condiciones de modificación. Revisa el boceto o modelo y confirma por escrito los detalles importantes, como un grabado o una talla. Las referencias sirven de orientación; la viabilidad depende del diseño y del proceso de fabricación.", "Al recibir la joya, compara el resultado con lo acordado y revisa el ajuste. Pide instrucciones de cuidado y conserva la documentación del encargo. Para comenzar una consulta, utiliza la sección Contacto e indica el tipo de pieza y las características que deseas conversar."]', 'blog/blog-9.jpg', 'PUBLICADO', '2026-08-28 00:00:00');
